@Composable private fun BatteryIndicator(){val context=LocalContext.current;var percent by remember{mutableIntStateOf(-1)};var charging by remember{mutableStateOf(false)};DisposableEffect(context){fun update(intent:Intent?){val level=intent?.getIntExtra(BatteryManager.EXTRA_LEVEL,-1)?:-1;val scale=intent?.getIntExtra(BatteryManager.EXTRA_SCALE,-1)?:-1;val status=intent?.getIntExtra(BatteryManager.EXTRA_STATUS,-1)?:-1;percent=if(level>=0&&scale>0)(level*100/scale) else -1;charging=status==BatteryManager.BATTERY_STATUS_CHARGING||status==BatteryManager.BATTERY_STATUS_FULL};val receiver=object:BroadcastReceiver(){override fun onReceive(c:Context?,intent:Intent?){update(intent)}};update(context.registerReceiver(receiver,IntentFilter(Intent.ACTION_BATTERY_CHANGED)));onDispose{runCatching{context.unregisterReceiver(receiver)}}};Row(Modifier.padding(end=14.dp),verticalAlignment=Alignment.CenterVertically){VerticalBattery(percent,charging);Spacer(Modifier.width(7.dp));Text(if(percent>=0)"$percent%" else "–",color=Color.White,fontSize=17.sp,fontWeight=FontWeight.Bold)}}
@Composable private fun VerticalBattery(percent:Int,charging:Boolean){val level=percent.coerceIn(0,100)/100f;val fill=when{percent<=20->Color(0xFFF44336);percent<=40->Color(0xFFFF9F1C);percent<=60->Color(0xFFDCE814);else->Color(0xFF16A34A)};Canvas(Modifier.width(22.dp).height(32.dp)){val terminalWidth=size.width*.38f;val bodyTop=size.height*.12f;drawRoundRect(Color.White,topLeft=Offset((size.width-terminalWidth)/2,0f),size=androidx.compose.ui.geometry.Size(terminalWidth,bodyTop*1.35f),cornerRadius=androidx.compose.ui.geometry.CornerRadius(2f,2f));drawRoundRect(Color.White,topLeft=Offset(1f,bodyTop),size=androidx.compose.ui.geometry.Size(size.width-2f,size.height-bodyTop-1f),cornerRadius=androidx.compose.ui.geometry.CornerRadius(3f,3f),style=Stroke(width=2.5f));val innerLeft=4.5f;val innerTop=bodyTop+4f;val innerBottom=size.height-4f;val available=(innerBottom-innerTop).coerceAtLeast(0f);val filled=available*level;if(filled>0f)drawRect(fill,topLeft=Offset(innerLeft,innerBottom-filled),size=androidx.compose.ui.geometry.Size(size.width-innerLeft*2,filled));if(charging){val p=androidx.compose.ui.graphics.Path().apply{moveTo(size.width*.58f,bodyTop+3f);lineTo(size.width*.35f,size.height*.55f);lineTo(size.width*.53f,size.height*.55f);lineTo(size.width*.40f,size.height-4f);lineTo(size.width*.70f,size.height*.46f);lineTo(size.width*.52f,size.height*.46f);close()};drawPath(p,Color.White)}}}
