@Composable private fun TodayScreen(vm:MainViewModel,onDetail:(Long)->Unit,onPlaces:()->Unit,onRoutePlan:(Long)->Unit){val days by vm.days.collectAsState();val settings by vm.settings.collectAsState();val places by vm.places.collectAsState();val now=LiveTick();val open=days.firstOrNull{d->d.events.none{it.type==EventType.WORK_END}};val today=open?:days.firstOrNull{it.day.date==LocalDate.now().toString()};val closed=today?.events?.any{it.type==EventType.WORK_END}==true;val planFlow=remember(today?.day?.id){vm.repo.plans(today?.day?.id?:-1)};val plans by planFlow.collectAsState(initial=emptyList());val recommended=plans.filter{!it.visited}.sortedBy{it.sortHint?:Int.MAX_VALUE}.mapNotNull{plan->places.firstOrNull{it.id==plan.placeId}};val current=settings.currentPlaceId?.takeIf{id->plans.any{it.placeId==id}}?.let{id->places.firstOrNull{it.id==id}};val ctx=LocalContext.current;var editEvent by remember{mutableStateOf<WorkEvent?>(null)};var manualType by remember{mutableStateOf<EventType?>(null)};var pendingClose by remember{mutableStateOf<Pair<EventType,Long>?>(null)};var expectedTripEnd by remember{mutableStateOf<Long?>(null)};val base=places.firstOrNull{it.active&&(it.type==PlaceType.BAKERY||it.type==PlaceType.HOME)};LaunchedEffect(today?.day?.id,recommended.map{it.id},recommended.map{it.averageDwellMillis},current?.id,today?.events?.lastOrNull()?.type){expectedTripEnd=null;if(today?.events?.lastOrNull()?.type==EventType.TRIP_START&&base!=null){runCatching{val start=current?:base;val remaining=recommended.filter{it.id!=start.id&&it.id!=base.id};val path=listOf(start)+remaining+listOf(base);val unique=path.distinctBy{it.id};val matrix=roadMatrix(unique);val indexes=unique.mapIndexed{i,p->p.id to i}.toMap();val drivingSeconds=path.zipWithNext().sumOf{matrix.durations[indexes.getValue(it.first.id)][indexes.getValue(it.second.id)]};val dwellMillis=remaining.sumOf{it.averageDwellMillis.coerceAtLeast(0)};expectedTripEnd=System.currentTimeMillis()+(drivingSeconds*1000).toLong()+dwellMillis}}};val permissions=rememberLauncherForActivityResult(ActivityResultContracts.RequestMultiplePermissions()){};fun service(id:Long,start:Boolean){val i=Intent(ctx,TrackingService::class.java).setAction(if(start)TrackingService.ACTION_START else TrackingService.ACTION_STOP).putExtra(TrackingService.EXTRA_DAY,id);if(start)ctx.startForegroundService(i)else ctx.startService(i)};fun start(ts:Long=System.currentTimeMillis()){vm.run{val id=vm.repo.startWork(ts);service(id,true)}};editEvent?.let{e->EventDialog(e,{editEvent=null},{vm.run{vm.repo.updateEvent(it)};editEvent=null},{vm.run{vm.repo.deleteEvent(e)};editEvent=null})};manualType?.let{type->ManualTimeDialog(type,{manualType=null}){ts->if(type==EventType.WORK_START&&(today==null||closed))start(ts)else if(type==EventType.TRIP_END||type==EventType.WORK_END)pendingClose=type to ts else today?.let{d->vm.run{vm.repo.addEvent(d.day.id,type,ts)}};manualType=null}};pendingClose?.let{(type,ts)->AlertDialog(onDismissRequest={pendingClose=null},title={Text(if(type==EventType.WORK_END)"Munka lezárása" else "Út lezárása")},text={Text(if(type==EventType.WORK_END)"Biztosan befejezed a munkát?" else "Biztosan rögzíted a visszaérkezést?")},confirmButton={Button({today?.let{d->vm.run{vm.repo.addEvent(d.day.id,type,ts);if(type==EventType.WORK_END)service(d.day.id,false)}};pendingClose=null}){Text("Igen, lezárom")}},dismissButton={TextButton({pendingClose=null}){Text("Mégse")}})};LazyColumn(contentPadding=PaddingValues(12.dp),verticalArrangement=Arrangement.spacedBy(10.dp)){item{TodayDateHeader(open,now)};if(today==null){item{SummaryCard(DaySummary(0,0,0,0.0,0),settings=settings)};item{RRCard(Modifier.fillMaxWidth()){WorkEventRow(EventType.WORK_START,null,{start()},{manualType=EventType.WORK_START})}};item{VersionFooter()}}else{val sum=today.summary(settings,now);val events=today.events.sortedBy{it.timestamp};item{SummaryCard(sum,settings=settings,expectedTripEnd=expectedTripEnd)};if(!closed)item{OutlinedButton(onClick=onPlaces,modifier=Modifier.fillMaxWidth().height(50.dp),shape=RoundedCornerShape(10.dp)){Icon(Icons.Default.FormatListNumbered,null,Modifier.size(28.dp));Spacer(Modifier.width(10.dp));Text("Mai megállók",fontWeight=FontWeight.Bold)}};if((recommended.isNotEmpty()||current!=null||base!=null)&&!closed)item{RouteRecommendation(if(recommended.isEmpty())listOfNotNull(base) else recommended,onPlaces,{today.day.id.let(onRoutePlan)},current)};item{RRCard(Modifier.fillMaxWidth()){events.forEach{e->WorkEventRow(e.type,e.timestamp,{editEvent=e},{editEvent=e})};val last=events.lastOrNull()?.type;if(last==EventType.TRIP_START)WorkEventRow(EventType.TRIP_END,null,{pendingClose=EventType.TRIP_END to System.currentTimeMillis()},{manualType=EventType.TRIP_END})else if(last!=EventType.WORK_END)AddTripRow{if(ContextCompat.checkSelfPermission(ctx,Manifest.permission.ACCESS_FINE_LOCATION)!=PackageManager.PERMISSION_GRANTED)permissions.launch(arrayOf(Manifest.permission.ACCESS_FINE_LOCATION,Manifest.permission.POST_NOTIFICATIONS));vm.run{vm.repo.nextAction(today.day.id);service(today.day.id,true)}};if(last!=EventType.WORK_END)WorkEventRow(EventType.WORK_END,null,{pendingClose=EventType.WORK_END to System.currentTimeMillis()},{manualType=EventType.WORK_END})}};if(closed)item{PrimaryButton("Új munkakezdés"){start()}};item{VersionFooter()}}}}
