@Composable private fun LogScreen(vm:MainViewModel,onDay:(Long)->Unit){val days by vm.days.collectAsState();val settings by vm.settings.collectAsState();val places by vm.places.collectAsState();val visibleDays=days.filter{d->d.events.any{it.type==EventType.WORK_START}};LazyColumn(contentPadding=PaddingValues(horizontal=12.dp),verticalArrangement=Arrangement.spacedBy(6.dp)){item{ScreenTitle("Napló")};item{PeriodSelector()};itemsIndexed(visibleDays,key={_,d->d.day.id}){index,d->val s=d.summary(settings);val date=LocalDate.parse(d.day.date);val events=d.events.sortedBy{it.timestamp};val stopPlans by remember(d.day.id){vm.repo.plans(d.day.id)}.collectAsState(initial=emptyList());val fuelIds=places.filter{it.type==PlaceType.FUEL}.map{it.id}.toSet();val regularVisited=stopPlans.count{it.visited&&it.placeId !in fuelIds};val fuelVisited=stopPlans.count{it.visited&&it.placeId in fuelIds};val manualVisited=stopPlans.count{it.visited&&it.completionMode=="MANUAL"};Column{if(index>0&&visibleDays[index-1].day.periodId!=d.day.periodId)PeriodBoundary();RRCard(Modifier.fillMaxWidth().clickable{onDay(d.day.id)}){Row(Modifier.padding(horizontal=9.dp,vertical=8.dp),verticalAlignment=Alignment.CenterVertically){Column(Modifier.width(49.dp),horizontalAlignment=Alignment.CenterHorizontally){Text(date.format(DateTimeFormatter.ofPattern("MMM",Locale("hu"))).uppercase().trimEnd('.'),fontSize=10.sp,color=DarkGray,fontWeight=FontWeight.Bold);Text(date.dayOfMonth.toString(),fontSize=26.sp,color=Navy,fontWeight=FontWeight.Bold)};Column(Modifier.width(72.dp)){Row(verticalAlignment=Alignment.CenterVertically){Icon(Icons.Default.PlayCircle,"Kezdés",tint=Green,modifier=Modifier.size(16.dp));Spacer(Modifier.width(4.dp));Text(events.firstOrNull()?.let{time(it.timestamp)}?:"–",fontWeight=FontWeight.Bold,fontSize=12.sp)};Spacer(Modifier.height(5.dp));Row(verticalAlignment=Alignment.CenterVertically){Icon(Icons.Default.StopCircle,"Befejezés",tint=DarkGray,modifier=Modifier.size(16.dp));Spacer(Modifier.width(4.dp));Text(events.lastOrNull()?.let{time(it.timestamp)}?:"–",fontWeight=FontWeight.Bold,fontSize=12.sp)}};VerticalDivider(Modifier.height(48.dp).padding(horizontal=4.dp),color=Border);Column(Modifier.weight(1f),verticalArrangement=Arrangement.spacedBy(2.dp)){LogMetric(Icons.Default.Schedule,"Munkaidő",duration(s.workMillis),Green);LogMetric(Icons.Default.DirectionsCar,"Útidő",duration(s.travelMillis),Blue);LogMetric(Icons.Default.Route,"Távolság",String.format(Locale("hu"),"%.1f km",s.distanceMeters/1000),Orange);LogMetric(Icons.Default.Place,"Megállók",if(fuelVisited>0)"$regularVisited + ⛽ $fuelVisited" else regularVisited.toString(),Navy);if(manualVisited>0)LogMetric(Icons.Default.TouchApp,"Kézi teljesítés",manualVisited.toString(),Orange)};Icon(Icons.Default.ChevronRight,null,tint=DarkGray,modifier=Modifier.size(18.dp))}}}}}}
