@Composable private fun EarningsScreen(vm:MainViewModel){
    val days by vm.days.collectAsState();val periods by vm.periods.collectAsState();val settings by vm.settings.collectAsState();val now=LiveTick()
    val activePeriod=periods.firstOrNull{it.endDate==null};val periodDays=days.filter{activePeriod==null||it.day.date>=activePeriod.startDate};val live=periodDays.any{d->d.events.none{it.type==EventType.WORK_END}};val sums=periodDays.map{it.summary(settings,now)};val lastDate=periodDays.maxOfOrNull{it.day.date}?:activePeriod?.startDate?:LocalDate.now().toString()
    LazyColumn(contentPadding=PaddingValues(horizontal=12.dp),verticalArrangement=Arrangement.spacedBy(10.dp)){
        item{ScreenTitle("Kereset")}
        item{RRCard(Modifier.fillMaxWidth()){Row(Modifier.padding(12.dp),verticalAlignment=Alignment.CenterVertically){Icon(Icons.Default.DateRange,null,tint=Navy);Spacer(Modifier.width(8.dp));Column{Text("Aktuális kereseti időszak",fontSize=10.sp,color=DarkGray);Text("${activePeriod?.startDate?:"–"} – $lastDate",fontWeight=FontWeight.Bold,fontSize=13.sp)}}}}
        item{RRCard(Modifier.fillMaxWidth()){Column(Modifier.fillMaxWidth().padding(22.dp),horizontalAlignment=Alignment.CenterHorizontally){Icon(Icons.Default.AccountBalanceWallet,null,tint=Green,modifier=Modifier.size(35.dp));Text(if(live)"Eddigi kereset (élő)" else "Időszaki kereset",fontSize=12.sp,color=DarkGray);Text(money(sums.sumOf{it.earnings}),fontSize=32.sp,fontWeight=FontWeight.Bold,color=Green);if(live)Text("Frissítve: ${time(now)}",fontSize=10.sp,color=DarkGray)}}}
        item{RRCard(Modifier.fillMaxWidth()){EarningsCard("Munkaidő",longDuration(sums.sumOf{it.workMillis}),Green,Icons.Default.Schedule);HorizontalDivider();EarningsCard("Óradíj",money(settings.hourlyRate),Orange,Icons.Default.Payments);HorizontalDivider();EarningsCard("Ledolgozott munkák","${periodDays.size}",Navy,Icons.Default.Work)}}
    }
}
private enum class StatsPeriod(val title:String){WEEK("Hét"),MONTH("Hónap"),SETTLEMENT("Elszámolási időszak"),CUSTOM("Egyéni időszak")}
private data class PlaceStats(val place:LocationPlace,val visits:List<PlaceVisit>){val durations=visits.mapNotNull{it.dwellDurationMillis?:if(it.arrivalTime!=null&&it.departureTime!=null)(it.departureTime-it.arrivalTime).coerceAtLeast(0)else null};val total=durations.sum();val average=if(durations.isEmpty())0 else total/durations.size;val shortest=durations.minOrNull()?:0;val longest=durations.maxOrNull()?:0}
@Composable private fun StatsScreen(vm:MainViewModel){
 val days by vm.days.collectAsState();val periods by vm.repo.periods.collectAsState(initial=emptyList());val settings by vm.settings.collectAsState();val places by vm.places.collectAsState();val allVisits by vm.repo.visits.collectAsState(initial=emptyList())
 var period by remember{mutableStateOf(StatsPeriod.MONTH)};var tab by remember{mutableIntStateOf(0)};var customStart by remember{mutableStateOf(LocalDate.now().withDayOfMonth(1).toString())};var customEnd by remember{mutableStateOf(LocalDate.now().toString())};var customDialog by remember{mutableStateOf(false)};var sort by remember{mutableStateOf("COUNT")};var detail by remember{mutableStateOf<PlaceStats?>(null)}
 val latestDate=days.mapNotNull{runCatching{LocalDate.parse(it.day.date)}.getOrNull()}.maxOrNull()?:LocalDate.now();val activePeriod=periods.firstOrNull{it.endDate==null}?:periods.maxByOrNull{it.startDate}
 val range=when(period){StatsPeriod.WEEK->latestDate.minusDays(6)..latestDate;StatsPeriod.MONTH->latestDate.withDayOfMonth(1)..latestDate.withDayOfMonth(latestDate.lengthOfMonth());StatsPeriod.SETTLEMENT->{val start=activePeriod?.startDate?.let{runCatching{LocalDate.parse(it)}.getOrNull()}?:latestDate.withDayOfMonth(1);val end=activePeriod?.endDate?.let{runCatching{LocalDate.parse(it)}.getOrNull()}?:latestDate;start..end};StatsPeriod.CUSTOM->{val start=runCatching{LocalDate.parse(customStart)}.getOrDefault(latestDate);val end=runCatching{LocalDate.parse(customEnd)}.getOrDefault(latestDate);minOf(start,end)..maxOf(start,end)}}
 val filtered=days.filter{runCatching{LocalDate.parse(it.day.date) in range}.getOrDefault(false)}.sortedBy{it.day.date};val dayIds=filtered.map{it.day.id}.toSet();val visits=allVisits.filter{it.workDayId in dayIds};val summaries=filtered.map{it to it.summary(settings)};val placeById=places.associateBy{it.id};val dwell=visits.sumOf{it.dwellDurationMillis?:if(it.arrivalTime!=null&&it.departureTime!=null)(it.departureTime-it.arrivalTime).coerceAtLeast(0)else 0};val work=summaries.sumOf{it.second.workMillis};val travel=summaries.sumOf{it.second.travelMillis};val distance=summaries.sumOf{it.second.distanceMeters};val earnings=summaries.sumOf{it.second.earnings};val workDays=filtered.count{it.events.any{e->e.type==EventType.WORK_START}};val deliveryVisits=visits.count{placeById[it.placeId]?.type!=PlaceType.FUEL};val placeStats=visits.groupBy{it.placeId}.mapNotNull{(id,v)->placeById[id]?.let{PlaceStats(it,v)}};val sortedPlaces=when(sort){"TOTAL"->placeStats.sortedByDescending{it.total};"AVERAGE"->placeStats.sortedByDescending{it.average};else->placeStats.sortedByDescending{it.visits.size}}
 val longestDay=summaries.maxByOrNull{it.second.distanceMeters};val shortestDay=summaries.minByOrNull{it.second.distanceMeters};val allTrips=filtered.flatMap{d->d.trips.map{d.day.date to it}};val longestTrip=allTrips.maxByOrNull{it.second.distanceMeters};val tabs=listOf("Áttekintés","Közlekedés","Megállók","Grafikonok")
 detail?.let{PlaceVisitDetails(it,filtered.associate{d->d.day.id to d.day.date}){detail=null}}
 if(customDialog)CustomStatsPeriodDialog(customStart,customEnd,{customDialog=false}){a,b->customStart=a;customEnd=b;period=StatsPeriod.CUSTOM;customDialog=false}
 LazyColumn(contentPadding=PaddingValues(horizontal=12.dp,vertical=0.dp),verticalArrangement=Arrangement.spacedBy(10.dp)){
  item{ScreenTitle("Statisztika")};item{LazyRow(horizontalArrangement=Arrangement.spacedBy(6.dp)){items(StatsPeriod.entries){p->FilterChip(period==p,{if(p==StatsPeriod.CUSTOM)customDialog=true else period=p},{Text(p.title,fontSize=11.sp)},leadingIcon={Icon(when(p){StatsPeriod.WEEK->Icons.Default.DateRange;StatsPeriod.MONTH->Icons.Default.CalendarMonth;StatsPeriod.SETTLEMENT->Icons.Default.AccountBalanceWallet;StatsPeriod.CUSTOM->Icons.Default.EditCalendar},null,Modifier.size(17.dp))})}}};item{RRCard(Modifier.fillMaxWidth().clickable(enabled=period==StatsPeriod.CUSTOM){customDialog=true}){Row(Modifier.padding(11.dp),verticalAlignment=Alignment.CenterVertically){Icon(Icons.Default.CalendarToday,null,tint=Blue);Spacer(Modifier.width(9.dp));Text("${range.start.format(DateTimeFormatter.ofPattern("yyyy.MM.dd."))} – ${range.endInclusive.format(DateTimeFormatter.ofPattern("yyyy.MM.dd."))}",fontWeight=FontWeight.Bold,fontSize=13.sp)}}};item{ScrollableTabRow(selectedTabIndex=tab,containerColor=Color.White,edgePadding=0.dp){tabs.forEachIndexed{i,title->Tab(tab==i,{tab=i},text={Text(title,fontSize=11.sp,fontWeight=if(tab==i)FontWeight.Bold else FontWeight.Normal)})}}}
  when(tab){
   0->{item{Row(horizontalArrangement=Arrangement.spacedBy(8.dp)){StatsHighlight("Munkaidő",duration(work),Icons.Default.Schedule,Green,Modifier.weight(1f));StatsHighlight("Távolság",String.format(Locale("hu"),"%.1f km",distance/1000),Icons.Default.Route,Orange,Modifier.weight(1f))}};item{Row(horizontalArrangement=Arrangement.spacedBy(8.dp)){StatsHighlight("Vezetési idő",duration(travel),Icons.Default.DirectionsCar,Blue,Modifier.weight(1f));StatsHighlight("Kereset","${earnings} Ft",Icons.Default.AccountBalanceWallet,Color(0xFF7B1FA2),Modifier.weight(1f))}};item{RRCard(Modifier.fillMaxWidth()){Column{StatsLine(Icons.Default.Timer,"Megállóknál töltött idő",duration(dwell));StatsLine(Icons.Default.Work,"Munkanapok száma",workDays.toString());StatsLine(Icons.Default.Place,"Megállások / kiszállítások",deliveryVisits.toString())}}};item{AverageWorkdayCard(workDays,work,distance,travel,dwell,deliveryVisits)}}
   1->{item{RRCard(Modifier.fillMaxWidth()){Column{StatsLine(Icons.Default.Route,"Napi átlagos távolság",if(workDays>0)String.format(Locale("hu"),"%.1f km",distance/1000/workDays)else"–");StatsLine(Icons.Default.DirectionsCar,"Átlagos vezetési idő / munkanap",if(workDays>0)duration(travel/workDays)else"–");StatsLine(Icons.Default.AltRoute,"Átlagos távolság / út",if(allTrips.isNotEmpty())String.format(Locale("hu"),"%.1f km",distance/1000/allTrips.size)else"–");StatsLine(Icons.Default.TrendingUp,"Leghosszabb munkanap",longestDay?.let{"${String.format(Locale("hu"),"%.1f km",it.second.distanceMeters/1000)} · ${it.first.day.date}"}?:"–");StatsLine(Icons.Default.TrendingDown,"Legrövidebb munkanap",shortestDay?.let{"${String.format(Locale("hu"),"%.1f km",it.second.distanceMeters/1000)} · ${it.first.day.date}"}?:"–");StatsLine(Icons.Default.Straighten,"Leghosszabb egybefüggő útszakasz",longestTrip?.let{"${String.format(Locale("hu"),"%.1f km",it.second.distanceMeters/1000)} · ${it.first}"}?:"–");StatsLine(Icons.Default.Speed,"Megtett km / munkaóra",if(work>0)String.format(Locale("hu"),"%.1f km/óra",distance/1000/(work/3600000.0))else"–")}}}}
   2 -> {
    item {
     LazyRow(horizontalArrangement=Arrangement.spacedBy(6.dp)) {
      items(listOf("COUNT" to "Látogatások", "TOTAL" to "Összes idő", "AVERAGE" to "Átlagos idő")) { option ->
       FilterChip(sort == option.first, { sort = option.first }, { Text(option.second, fontSize=11.sp) })
      }
     }
    }
    if (sortedPlaces.isEmpty()) {
     item { EmptyStats("A kiválasztott időszakban még nincs lezárt megállólátogatás.") }
    } else {
     items(sortedPlaces, key={ it.place.id }) { placeStat -> PlaceStatsCard(placeStat) { detail=placeStat } }
    }
   }
   3 -> {
    item { BarChartCard("Megtett kilométer naponta", summaries.map { it.second.distanceMeters.toFloat()/1000 }, Orange) }
    item { StackedWorkChart(summaries.map { (day, summary) -> Triple(summary.travelMillis, visits.filter { it.workDayId==day.day.id }.sumOf { it.dwellDurationMillis?:0 }, summary.workMillis) }) }
    item { PlaceTimeChart(placeStats.sortedByDescending { it.total }.take(10)) }
   }
  }
 }
}
