@Composable private fun StackedWorkChart(rows:List<Triple<Long,Long,Long>>){RRCard(Modifier.fillMaxWidth()){Column(Modifier.padding(12.dp)){Text("Munkaidő napi felosztása",fontWeight=FontWeight.Bold,color=Navy);Spacer(Modifier.height(8.dp));Canvas(Modifier.fillMaxWidth().height(120.dp)){val values=if(rows.isEmpty())listOf(Triple(0L,0L,1L))else rows.takeLast(31);val max=values.maxOf{it.third}.coerceAtLeast(1);val gap=size.width/values.size;values.forEachIndexed{i,(driving,stopped,total)->val x=gap*(i+.2f);val width=gap*.6f;val driveH=size.height*driving/max;val stopH=size.height*stopped.coerceAtMost((total-driving).coerceAtLeast(0))/max;val otherH=(size.height*(total-driving-stopped).coerceAtLeast(0)/max);var bottom=size.height;drawRect(Blue,Offset(x,bottom-driveH),androidx.compose.ui.geometry.Size(width,driveH));bottom-=driveH;drawRect(Orange,Offset(x,bottom-stopH),androidx.compose.ui.geometry.Size(width,stopH));bottom-=stopH;drawRect(Green,Offset(x,bottom-otherH),androidx.compose.ui.geometry.Size(width,otherH))}};Row(horizontalArrangement=Arrangement.spacedBy(12.dp)){ChartLegend("Vezetés",Blue);ChartLegend("Megálló",Orange);ChartLegend("Egyéb",Green)}}}}
