private data class StorageSizes(val app:Long=0,val data:Long=0,val photos:Long=0)
private fun readableBytes(bytes:Long):String=when{bytes>=1024L*1024*1024->String.format(Locale("hu"),"%.2f GB",bytes/(1024.0*1024*1024));bytes>=1024L*1024->String.format(Locale("hu"),"%.1f MB",bytes/(1024.0*1024));bytes>=1024->String.format(Locale("hu"),"%.1f kB",bytes/1024.0);else->"$bytes B"}
@Composable private fun StorageUsageCard(places:List<LocationPlace>){val ctx=LocalContext.current;var sizes by remember{mutableStateOf(StorageSizes())};LaunchedEffect(places.map{listOf(it.photoPath,it.entrancePhotoPath)}){sizes=withContext(Dispatchers.IO){val photoFiles=places.flatMap{listOfNotNull(it.photoPath,it.entrancePhotoPath)}.distinct().map(::File);val photoPaths=photoFiles.map{it.absolutePath}.toSet();val photos=photoFiles.filter{it.isFile}.sumOf{it.length()};val app=(listOfNotNull(ctx.applicationInfo.sourceDir)+ctx.applicationInfo.splitSourceDirs.orEmpty()).map(::File).filter{it.isFile}.sumOf{it.length()};val data=File(ctx.applicationInfo.dataDir).walkTopDown().filter{it.isFile&&it.absolutePath !in photoPaths&&!it.absolutePath.contains("${File.separator}cache${File.separator}")}.sumOf{it.length()};StorageSizes(app,data,photos)}};val total=sizes.app+sizes.data+sizes.photos;RRCard(Modifier.fillMaxWidth().padding(top=8.dp)){Column(Modifier.padding(14.dp),verticalArrangement=Arrangement.spacedBy(9.dp)){Row(verticalAlignment=Alignment.CenterVertically){Surface(color=Blue.copy(alpha=.12f),shape=RoundedCornerShape(10.dp),modifier=Modifier.size(38.dp)){Box(contentAlignment=Alignment.Center){Icon(Icons.Default.Storage,null,tint=Blue,modifier=Modifier.size(22.dp))}};Spacer(Modifier.width(10.dp));Column(Modifier.weight(1f)){Text("Tárhelyhasználat",fontWeight=FontWeight.Bold,color=Navy,fontSize=14.sp);Text("Az alkalmazás helyfoglalása",fontSize=10.sp,color=DarkGray)}};HorizontalDivider(color=Border);StorageMetric(Icons.Default.PhoneAndroid,"Alkalmazás",sizes.app,Blue);StorageMetric(Icons.Default.InsertDriveFile,"Adatok",sizes.data,Green);StorageMetric(Icons.Default.PhotoLibrary,"Képek",sizes.photos,Orange);HorizontalDivider(color=Border);StorageMetric(Icons.Default.PieChart,"Összesen",total,Navy,true)}}}
@Composable private fun StorageMetric(icon:ImageVector,label:String,size:Long,color:Color,emphasized:Boolean=false){Row(Modifier.fillMaxWidth().height(if(emphasized)38.dp else 32.dp),verticalAlignment=Alignment.CenterVertically){Icon(icon,null,tint=color,modifier=Modifier.size(if(emphasized)22.dp else 19.dp));Spacer(Modifier.width(9.dp));Text(label,Modifier.weight(1f),fontSize=if(emphasized)13.sp else 12.sp,fontWeight=if(emphasized)FontWeight.Bold else FontWeight.Medium,color=if(emphasized)Navy else DarkGray);Text(readableBytes(size),fontWeight=FontWeight.Bold,fontSize=if(emphasized)15.sp else 12.sp,color=color)}}
