@Composable
private fun MunicipalityColorsDialog(
    places:List<LocationPlace>,
    settings:AppSettings,
    onDismiss:()->Unit,
    onSave:(String)->Unit
){
    val names=places.map(::municipality).filter{it.isNotBlank()}.distinct().sortedWith(String.CASE_INSENSITIVE_ORDER)
    var colors by remember(settings.municipalityColors){mutableStateOf(municipalityMap(settings.municipalityColors))}
    AlertDialog(
        onDismissRequest=onDismiss,
        title={Text("Településszínek")},
        text={
            LazyColumn(Modifier.heightIn(max=440.dp),verticalArrangement=Arrangement.spacedBy(8.dp)){
                items(names){name->
                    Column{
                        Text(name,fontWeight=FontWeight.Bold,fontSize=14.sp)
                        LazyRow(horizontalArrangement=Arrangement.spacedBy(7.dp),contentPadding=PaddingValues(vertical=3.dp)){
                            items(MunicipalityPalette){raw->
                                val fallback=MunicipalityPalette[(name.hashCode().toLong().absoluteValue%MunicipalityPalette.size).toInt()]
                                val selected=(colors[name]?:fallback)==raw
                                Surface(
                                    color=Color(raw),
                                    shape=CircleShape,
                                    border=if(selected)BorderStroke(3.dp,Navy) else null,
                                    modifier=Modifier.size(30.dp).clickable{colors=colors+(name to raw)}
                                ){}
                            }
                        }
                    }
                }
            }
        },
        confirmButton={
            Button({
                val value=JSONObject()
                colors.forEach{(key,color)->value.put(key,color)}
                onSave(value.toString())
            }){Text("Mentés")}
        },
        dismissButton={TextButton(onDismiss){Text("Mégse")}}
    )
}
