private suspend fun remoteRoadRoute(points:List<LocationPlace>):RoadRoute=withContext(Dispatchers.IO){
    require(points.size>=2){"Az útvonalhoz legalább két pont szükséges."};require(points.all{it.latitude!=null&&it.longitude!=null}){"Hiányzó GPS-koordináta."}
    val coords=points.joinToString(";"){"${it.longitude},${it.latitude}"};val connection=(URL("https://router.project-osrm.org/route/v1/driving/$coords?overview=full&geometries=geojson&steps=false").openConnection() as HttpURLConnection).apply{connectTimeout=15000;readTimeout=30000;setRequestProperty("User-Agent","RoadRecord-Android/${BuildConfig.VERSION_NAME}")}
    try{if(connection.responseCode !in 200..299)error("Az útvonal-szolgáltatás nem elérhető (${connection.responseCode}).");val root=JSONObject(connection.inputStream.bufferedReader().use{it.readText()});val route=root.getJSONArray("routes").getJSONObject(0);val coordinates=route.getJSONObject("geometry").getJSONArray("coordinates");val geometry=List(coordinates.length()){i->val pair=coordinates.getJSONArray(i);RouteGeoPoint(pair.getDouble(1),pair.getDouble(0))};RoadRoute(route.getDouble("duration"),route.getDouble("distance"),geometry)}finally{connection.disconnect()}
