    if(place.officialAddress.isBlank())return@withContext null;val query=URLEncoder.encode("${place.officialAddress}, Magyarország","UTF-8");val connection=(URL("https://nominatim.openstreetmap.org/search?format=jsonv2&limit=1&countrycodes=hu&q=$query").openConnection() as HttpURLConnection).apply{connectTimeout=15000;readTimeout=20000;setRequestProperty("User-Agent","RoadRecord-Android/${BuildConfig.VERSION_NAME} (sztankod@gmail.com)");setRequestProperty("Accept-Language","hu")}
