private fun routeMetrics(start:LocationPlace,end:LocationPlace?,stops:List<LocationPlace>,matrix:RoadMatrix):RouteResult{
    val all=(listOf(start)+stops+listOfNotNull(end)).distinctBy{it.id};val idx=all.mapIndexed{i,p->p.id to i}.toMap();val path=listOf(start)+stops+listOfNotNull(end)
