private fun airFallback(start:LocationPlace,end:LocationPlace?,stops:List<LocationPlace>,locked:Map<Long,Int>):RouteResult{if((listOf(start)+stops+listOfNotNull(end)).any{it.latitude==null||it.longitude==null})return RouteResult(stops,Double.NaN,Double.NaN,false);val result=MutableList<LocationPlace?>(stops.size){null};locked.forEach{(id,pos)->stops.firstOrNull{it.id==id}?.let{if(pos in result.indices)result[pos]=it}};val free=stops.filter{p->result.none{it?.id==p.id}}.toMutableList();var current=start;result.indices.forEach{i->if(result[i]==null){val next=free.minBy{routeDistance(current,it)};result[i]=next;free.remove(next);current=next}else current=result[i]!!};val route=result.filterNotNull();val path=listOf(start)+route+listOfNotNull(end);val km=path.zipWithNext().sumOf{sqrt(routeDistance(it.first,it.second))*111.0*1.25};return RouteResult(route,km/55.0*3600+route.sumOf{it.averageDwellMillis.coerceAtLeast(0)/1000.0},km*1000,false)}
